(async () => {
  const { existsSync, readFileSync } = await import('node:fs');
  const inputPath = process.env.INPUT_PATH;
  const outputPath = process.env.OUTPUT_PATH;
  if (!inputPath) throw new Error('Missing INPUT_PATH');
  if (!outputPath) throw new Error('Missing OUTPUT_PATH');
  if (!existsSync(inputPath)) throw new Error('Input file does not exist');
  const xmlData = readFileSync(inputPath, 'utf8');
  globalThis._xmlData = xmlData;
  globalThis._outputPath = outputPath;
})();

(async () => {
  const { writeFileSync } = await import('node:fs');
  const jspMod = await import('jsparsers');
  const jsp = jspMod.default || jspMod;
  const xmlParser = jsp.xml();
  const jsObj = xmlParser.parse(globalThis._xmlData);
  const tomlConverter = jsp.toml();
  const tomlStr = tomlConverter.toml(jsObj);
  writeFileSync(globalThis._outputPath, tomlStr, 'utf8');
  globalThis._tomlStr = tomlStr;
})();
